using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Xml;using BeamScheduleFormatter;
class PendingPowRowUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static T Get<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static BeamRow Row(){var r=new BeamRow{Mark="GB-1",Leg="2L",Diameter="O10",RevisedSpacing="1 - 50mm, REST AT 150mm TO FREE END"};r.Spacing=r.RevisedSpacing;for(int i=0;i<14;i++)r.Cells[i].Add("-");r.Cells[0][0]="300";r.Cells[1][0]="500";for(int i=2;i<8;i++)r.Cells[i][0]="2-O16";return r;}
 [STAThread]static void Main(){Application.EnableVisualStyles();AccessCodes.Granted=true;string previous=ProjectInfoStore.DirectoryPath,folder=Path.Combine(Path.GetTempPath(),"DTCE-pending-row-"+Guid.NewGuid().ToString("N"));ProjectInfoStore.DirectoryPath=folder;Directory.CreateDirectory(folder);try{using(var f=new ProgramOfWorksForm()){var beam=Get<EstimatorForm>(f,"beam");beam.AddManual(Row());beam.AddEntry("Valid member","GB-1","2","1");int pending=beam.AddEntry("Pending next row","GB-1","","");f.Recalculate();Check(f.WorksValidationIssues().Count>0,"Blank quantity stays pending");Check(f.WorksExcelTables().Count>0&&f.BillOfQuantities().Count>0,"Live POW summaries tolerate pending beam row");bool rejected=false;try{f.FinalQuantityTables();}catch{rejected=true;}Check(rejected,"Final export remains blocked while inputs are incomplete");string path=Path.Combine(folder,"Complete.pow.xml");f.SaveTo(path);var doc=new XmlDocument();doc.Load(path);var inner=new XmlDocument();inner.LoadXml(doc.DocumentElement["Beam"].InnerText);Check(inner.SelectNodes("//Entry").Count==2,"Full POW saves valid and pending beam rows");Check(((XmlElement)inner.SelectNodes("//Entry")[1]).GetAttribute("quantity")=="","Saving does not invent pending quantity");var grid=beam.WorksInputGrid;grid.Rows[0].Cells[5].Value="2";beam.Recalculate();object[] args={new Message(),Keys.Control|Keys.S};bool handled=(bool)typeof(ProgramOfWorksForm).GetMethod("ProcessCmdKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,args);Check(handled,"Ctrl+S handled at POW host");doc.Load(path);inner.LoadXml(doc.DocumentElement["Beam"].InnerText);Check(((XmlElement)inner.SelectNodes("//Entry")[0]).GetAttribute("quantity")=="2","Ctrl+S saves current edited values to existing whole-project file");using(var restored=new ProgramOfWorksForm()){restored.OpenFrom(path);var restoredGrid=Get<EstimatorForm>(restored,"beam").WorksInputGrid;Check(Convert.ToString(restoredGrid.Rows[1].Cells[5].Value)=="","Whole POW opens pending row with blank quantity");restored.Recalculate();Check(restored.BillOfQuantities().Count>0,"Restored pending row does not crash live BOQ");}beam.WorksSaved();}Console.WriteLine("PASS: "+checks+" native pending-row, strict export and whole-POW Ctrl+S checks");}finally{ProjectInfoStore.DirectoryPath=previous;if(Directory.Exists(folder))Directory.Delete(folder,true);}}
}
